/** 真实设备验证加密认证、任务落盘、字幕偏移、接力及 DLNA SOAP。 */
public final class FeatureSmoke extends Instrumentation {
 private Context context;
 @Override public void onCreate(Bundle b){super.onCreate(b);start();}
 private Object call(String type,String method,Class<?>[] args,Object... values)throws Exception{Method m=Class.forName("app.quanneng."+type).getDeclaredMethod(method,args);m.setAccessible(true);return m.invoke(null,values);}
 private void check(boolean ok,String message){if(!ok)throw new AssertionError(message);}
 private void rejected(String type,String method,Class<?>[] args,Object... values)throws Exception{try{call(type,method,args,values);throw new AssertionError("Unsafe input accepted: "+type);}catch(InvocationTargetException expected){}}
 @Override public void onStart(){PrivateTestAccess.install(this);Bundle result=new Bundle();try{context=getTargetContext();Activity activity=startActivitySync(new Intent().setComponent(new ComponentName("app.quanneng","app.quanneng.MainActivity")).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TASK));PrivateTestAccess.awaitUnlocked(this,activity);
  report("unlocked");policy();report("policy");subtitles();report("subtitles");handoff();report("handoff");vault();report("vault");queue();report("queue");soap();report("soap");tools();report("tools");
  for(String screen:new String[]{"LibraryActivity","SubtitleActivity","VaultActivity","NasActivity","CastActivity","HandoffActivity","DiagnosticsActivity","GestureSettingsActivity"}){ActivityMonitor monitor=addMonitor("app.quanneng."+screen,null,false);runOnMainSync(()->activity.startActivity(new Intent().setComponent(new ComponentName("app.quanneng","app.quanneng."+screen))));Activity opened=waitForMonitorWithTimeout(monitor,15000);removeMonitor(monitor);check(opened!=null,"Failed to open "+screen);PrivateTestAccess.awaitUnlocked(this,opened);runOnMainSync(opened::finish);SystemClock.sleep(200);}
  result.putString("stream","Vault round-trip/tamper/truncation, subtitle offsets, strict handoff, persisted queue, bounded XML, DLNA SOAP, five FFmpeg tools and 8 screens verified\nQUANNENG_FEATURES_OK\n");runOnMainSync(activity::finish);finish(Activity.RESULT_OK,result);
 }catch(Throwable e){e.printStackTrace();Throwable why=e instanceof InvocationTargetException?((InvocationTargetException)e).getTargetException():e;result.putString("stream","QUANNENG_FEATURES_FAILED: "+why+"\n");finish(Activity.RESULT_CANCELED,result);}}
 private void report(String s){Bundle b=new Bundle();b.putString("stream","FEATURE_STEP "+s+"\n");sendStatus(0,b);}
 private void policy()throws Exception{Class<?>[] s={String.class};for(String u:new String[]{"http://192.168.1.2/a","http://10.0.2.15/a","https://example.com/a"})call("NetworkPolicy","url",s,u);for(String u:new String[]{"http://example.com/a","http://127.0.0.1/a","https://u:p@example.com/","file:///tmp/x","http://192.168.1.999/a","javascript:alert(1)"})rejected("NetworkPolicy","url",s,u);rejected("NetworkIO","xml",new Class<?>[]{byte[].class},"<!DOCTYPE a [<!ENTITY x SYSTEM 'file:///etc/passwd'>]><a>&x;</a>".getBytes("UTF-8"));}
 private void subtitles()throws Exception{String source="1\n00:00:01,000 --> 00:00:02,500\n台词\n";String shifted=(String)call("SubtitleStore","shift",new Class<?>[]{String.class,long.class},source,750L);check(shifted.contains("00:00:01.750 --> 00:00:03.250")&&shifted.startsWith("WEBVTT"),"Subtitle shift failed");rejected("SubtitleStore","shift",new Class<?>[]{String.class,long.class},"broken",0L);}
 private void handoff()throws Exception{String raw=(String)call("Handoff","encode",new Class<?>[]{String.class,long.class},"https://example.com/video.mp4",12345L);Object decoded=call("Handoff","decode",new Class<?>[]{String.class},raw);check(decoded.toString().contains("12345"),"Handoff position lost");rejected("Handoff","decode",new Class<?>[]{String.class},"QUANNENG/1\n{\"version\":1,\"url\":\"file:///private\",\"position\":0}");rejected("Handoff","encode",new Class<?>[]{String.class,long.class},"https://example.com/v.mp4",-1L);}
 private byte[] bytes(File f)throws Exception{try(InputStream in=new FileInputStream(f);ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1)out.write(b,0,n);return out.toByteArray();}}
 private void vault()throws Exception{Uri source=Uri.parse("content://app.quanneng.tests.fixture/seek-fixture.mp4");File encrypted=(File)call("VaultStore","add",new Class<?>[]{Context.class,Uri.class},context,source);File clear=(File)call("VaultStore","open",new Class<?>[]{Context.class,File.class},context,encrypted);byte[] original;try(InputStream in=context.getContentResolver().openInputStream(source);ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1)out.write(b,0,n);original=out.toByteArray();}check(Arrays.equals(original,bytes(clear)),"Encrypted roundtrip mismatch");byte[] cipher=bytes(encrypted);check(!Arrays.equals(original,cipher),"Vault plaintext");File bad=new File(encrypted.getParentFile(),"tamper-test.qvault");cipher[cipher.length-1]^=1;try(FileOutputStream out=new FileOutputStream(bad)){out.write(cipher);}rejected("VaultStore","open",new Class<?>[]{Context.class,File.class},context,bad);try(FileOutputStream out=new FileOutputStream(bad)){out.write(cipher,0,cipher.length-32);}rejected("VaultStore","open",new Class<?>[]{Context.class,File.class},context,bad);bad.delete();encrypted.delete();call("VaultStore","purge",new Class<?>[]{Context.class},context);check(!clear.exists(),"Plaintext cache not purged");}
 private void queue()throws Exception{Object first=call("TaskStore","add",new Class<?>[]{Context.class,String.class,String.class},context,"download","https://example.com/a.mp4");Object second=call("TaskStore","add",new Class<?>[]{Context.class,String.class,String.class},context,"download","https://example.com/b.mp4");Class<?> j=first.getClass();Field state=j.getDeclaredField("state");state.setAccessible(true);state.set(first,"running");call("TaskStore","save",new Class<?>[]{Context.class,j},context,first);call("TaskStore","recover",new Class<?>[]{Context.class},context);List<?> jobs=(List<?>)call("TaskStore","list",new Class<?>[]{Context.class},context);check(jobs.size()>=2,"Queue persistence failed");Field id=j.getDeclaredField("id");id.setAccessible(true);for(Object o:jobs)if(id.get(o).equals(id.get(first))||id.get(o).equals(id.get(second)))check("paused".equals(state.get(o)),"Interrupted task not recovered");for(Object o:new Object[]{first,second}){File folder=(File)call("TaskStore","folder",new Class<?>[]{Context.class,j},context,o);call("TransferService","deleteFolder",new Class<?>[]{File.class},folder);}}
 private void tools()throws Exception{
  Class<?> runtime=Class.forName("app.quanneng.TransferRuntime"),tokenType=Class.forName("app.quanneng.TransferRuntime$Token"),progressType=Class.forName("app.quanneng.TransferRuntime$Progress");Constructor<?> ctor=tokenType.getDeclaredConstructor();ctor.setAccessible(true);Object token=ctor.newInstance(),progress=java.lang.reflect.Proxy.newProxyInstance(progressType.getClassLoader(),new Class<?>[]{progressType},(p,m,a)->null);File root=new File(context.getCacheDir(),"feature-tool-tests");root.mkdirs();File input=new File(root,"source.mp4");
  Method ffmpeg=runtime.getDeclaredMethod("runFFmpeg",Context.class,List.class,tokenType,progressType);ffmpeg.setAccessible(true);ffmpeg.invoke(null,context,Arrays.asList("-nostdin","-y","-f","lavfi","-i","testsrc=size=160x96:rate=5","-f","lavfi","-i","sine=frequency=440:sample_rate=44100","-t","1.5","-c:v","libx264","-pix_fmt","yuv420p","-c:a","aac",input.getAbsolutePath()),token,progress);
  Method tool=runtime.getDeclaredMethod("tool",Context.class,File.class,File.class,String.class,org.json.JSONObject.class,tokenType,progressType);tool.setAccessible(true);
  for(String mode:new String[]{"trim","audio","compress","snapshot","mute"}){File dir=new File(root,mode);dir.mkdirs();File result=(File)tool.invoke(null,context,input,dir,mode,new org.json.JSONObject().put("start",.2).put("end",1),ctor.newInstance(),progress);check(result.length()>0,"No result for "+mode);if(mode.equals("snapshot"))check(android.graphics.BitmapFactory.decodeFile(result.getAbsolutePath())!=null,"Invalid snapshot");else{android.media.MediaMetadataRetriever reader=new android.media.MediaMetadataRetriever();try{reader.setDataSource(result.getAbsolutePath());check(Long.parseLong(reader.extractMetadata(android.media.MediaMetadataRetriever.METADATA_KEY_DURATION))>0,"Invalid "+mode);if(!mode.equals("audio"))check(reader.getFrameAtTime()!=null,"Undecodable "+mode);if(mode.equals("mute"))check(reader.extractMetadata(android.media.MediaMetadataRetriever.METADATA_KEY_HAS_AUDIO)==null,"Mute retained audio");}finally{reader.release();}}}
  call("TransferService","deleteFolder",new Class<?>[]{File.class},root);
 }
 private void soap()throws Exception{String local=null;Enumeration<NetworkInterface> interfaces=NetworkInterface.getNetworkInterfaces();while(interfaces.hasMoreElements()){Enumeration<InetAddress> addresses=interfaces.nextElement().getInetAddresses();while(addresses.hasMoreElements()){InetAddress a=addresses.nextElement();if(a instanceof Inet4Address&&a.isSiteLocalAddress())local=a.getHostAddress();}}if(local==null)throw new AssertionError("No private network on test device");ServerSocket server=new ServerSocket(0);server.setSoTimeout(20000);String base="http://"+local+":"+server.getLocalPort();List<String> requests=Collections.synchronizedList(new ArrayList<>());final String origin=base;Thread mock=new Thread(()->{try{for(int i=0;i<4;i++)try(Socket s=server.accept()){BufferedReader in=new BufferedReader(new InputStreamReader(s.getInputStream(),"UTF-8"));String line=in.readLine();int length=0;String header;while((header=in.readLine())!=null&&!header.isEmpty())if(header.toLowerCase(Locale.ROOT).startsWith("content-length:"))length=Integer.parseInt(header.substring(15).trim());char[] body=new char[length];int n=0;while(n<length){int read=in.read(body,n,length-n);if(read<0)break;n+=read;}requests.add(line+new String(body));String response=i==0?"<root xmlns=\"urn:schemas-upnp-org:device-1-0\"><device><friendlyName>Fixture TV</friendlyName><serviceList><service><serviceType>urn:schemas-upnp-org:service:AVTransport:1</serviceType><controlURL>/control</controlURL></service></serviceList></device></root>":"<ok/>";byte[] b=response.getBytes("UTF-8");OutputStream out=s.getOutputStream();out.write(("HTTP/1.1 200 OK\r\nContent-Type: text/xml\r\nContent-Length: "+b.length+"\r\nConnection: close\r\n\r\n").getBytes("UTF-8"));out.write(b);out.flush();}}catch(Exception e){requests.add("ERROR:"+e);}finally{try{server.close();}catch(Exception ignored){}}});mock.start();Object device=call("DlnaClient","describe",new Class<?>[]{String.class},origin+"/device.xml");check(device!=null,"DLNA service parse failed");call("NetworkIO","request",new Class<?>[]{URL.class,String.class,String.class,String.class,String.class,byte[].class},new URL(origin+"/dav/"),"PROPFIND","Basic dGVzdDp0ZXN0","application/xml",null,"<propfind/>".getBytes("UTF-8"));call("DlnaClient","cast",new Class<?>[]{device.getClass(),String.class},device,"https://example.com/video.mp4?a=1&b=2");mock.join(5000);check(requests.size()==4&&requests.get(1).startsWith("PROPFIND /dav/")&&requests.get(2).contains("SetAVTransportURI")&&requests.get(2).contains("&amp;")&&requests.get(3).contains("<Speed>1</Speed>"),"DLNA SOAP invalid: "+requests);server.close();}
}
